import { useGesture } from '@use-gesture/react';
import { Bounds } from '@visx/brush/lib/types';
import clsx from 'clsx';
import React, { useState } from 'react';

import { HistogramCrosshair } from './HistogramCrosshair.js';
import { HistogramInspect } from './HistogramInspect.js';
import {
  divPlotLayout,
  svgPlotLayout,
} from '../../../../core/components/chart-grid/ChartGridRoot.sty.js';
import { useGridPlotSize } from '../../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { usePanning } from '../../../../core/components/zoom/hooks/usePanning.js';
import { ZoomBrush } from '../../../../core/components/zoom/ZoomBrush.js';
import { cursorStyle } from '../../../../core/components/zoom/ZoomCursors.sty.js';
import { DataPoint } from '../../../../core/types/data-point.js';
import {
  useCurrentDomainState,
  useSetState,
} from '../../../hooks/store/selectors.js';
import { useHistogramInteractions } from '../../../hooks/useHistogramInteractions.js';
import { useHistogramXFormatter } from '../../../hooks/useHistogramXFormatter.js';
import { useHistogramXScale } from '../../../hooks/useHistogramXScale.js';
import { useHistogramYScales } from '../../../hooks/useHistogramYScales.js';
import { useXAxisConfig } from '../../../hooks/useXAxisConfig.js';
import { HistogramBin } from '../../../types/histogram.js';
import { middleMouseClick } from '../constants.js';
import { brushOverlay } from '../HistogramOverlays.sty.js';
import { useClosestBinsByMouse } from '../hooks/useClosestBinsByMouse.js';
import { usePinnedAwarePosition } from '../hooks/usePinnedAwarePosition.js';

export interface HistogramDataPoint extends DataPoint {
  bin: HistogramBin;
}

type XZoomState = 'idle' | 'down' | 'dragging';

type PanState = 'idle' | 'panning';

export const HistogramExploreOverlay = () => {
  const mousePosition = usePinnedAwarePosition();
  const [leftScale] = useHistogramYScales();
  const { xScale, initialXScale } = useHistogramXScale();
  const bottomFormatter = useHistogramXFormatter();
  const { unit: xUnit } = useXAxisConfig();
  const { width, height } = useGridPlotSize();
  const setState = useSetState();
  const { onZoomChange, zoomX, pan } = useHistogramInteractions();
  const { closestBin } = useClosestBinsByMouse(mousePosition);
  const [xZoomState, setXZoomState] = useState<XZoomState>('idle');
  const isZoomXEnabled = zoomX?.enabled;
  const currentDomain = useCurrentDomainState();
  const isChartWithZoom = Boolean(currentDomain);
  const isPanEnabled = pan?.enabled && isChartWithZoom;
  const plotRef = React.useRef<HTMLDivElement>(null);
  const [panState, setPanState] = useState<PanState>('idle');

  const handleTogglePinTooltip = () => {
    const highlightedSeriesId = closestBin?.id ? [closestBin?.id] : undefined;

    setState((prev) => ({
      ...prev,
      highlightedSeriesIds: prev.overlays.pinnedTooltip
        ? undefined
        : highlightedSeriesId,
      overlays: {
        ...prev.overlays,
        pinnedTooltip: !prev.overlays.pinnedTooltip,
      },
    }));
  };

  const handleBrushEnd = (domain: Bounds) => {
    onZoomChange && onZoomChange(domain.x0, domain.x1, 'zoom-x');
    setState((prev) => ({
      ...prev,
      currentDomain: [domain.x0, domain.x1],
      zoom: {
        ...prev.zoom,
        zoomOutEnabled: true,
      },
    }));
    setXZoomState('down');
  };

  function handlePan(domain: number[]) {
    setState((prev) => ({
      ...prev,
      currentDomain: domain,
    }));
  }

  function handlePanEnd([min, max]: number[]) {
    setPanState('idle');
    onZoomChange?.(min, max, 'panning');
  }

  const { onDrag, onDragEnd } = usePanning({
    initialXScale,
    xScale,
    onPanning: handlePan,
    onPanningEnd: handlePanEnd,
  });

  const isNotPanning = panState !== 'panning';

  useGesture(
    {
      onDrag: (event) => {
        setPanState('panning');
        onDrag && onDrag(event);
      },
      onDragEnd,
    },
    {
      target: plotRef,
      eventOptions: { passive: false },
      drag: { pointer: { buttons: middleMouseClick } },
      enabled: isPanEnabled,
    },
  );

  const isNotDragging = xZoomState !== 'dragging';

  const handleClick = () => {
    if (xZoomState === 'idle') {
      handleTogglePinTooltip();
    }

    setXZoomState('idle');
  };

  return (
    <div
      ref={plotRef}
      onClick={handleClick}
      className={clsx(cursorStyle({ isPanEnabled }), divPlotLayout)}
    >
      {isNotDragging && isNotPanning && <HistogramInspect />}
      {isNotDragging && isNotPanning && <HistogramCrosshair />}
      {isZoomXEnabled && (
        <svg className={clsx(svgPlotLayout, brushOverlay)}>
          {isNotPanning && (
            <ZoomBrush
              width={width}
              height={height}
              yScale={leftScale}
              xScale={xScale}
              onBrushChange={() => setXZoomState('dragging')}
              onBrushEnd={handleBrushEnd}
              labelAccessor={(point) => bottomFormatter(point ?? 0, xUnit)}
            />
          )}
        </svg>
      )}
    </div>
  );
};
